#!/usr/bin/env bash
# Claude Code status line. Receives session JSON on stdin.
input=$(cat); cwd=$(echo "$input" | jq -r '.workspace.current_dir'); model=$(echo "$input" | jq -r '.model.display_name'); output_style=$(echo "$input" | jq -r '.output_style.name // "default"'); current_dir=$(basename "$cwd"); git_info=""; if git -C "$cwd" --no-optional-locks rev-parse --git-dir > /dev/null 2>&1; then branch=$(git -C "$cwd" --no-optional-locks rev-parse --abbrev-ref HEAD 2>/dev/null); if [[ -n $(git -C "$cwd" --no-optional-locks status --porcelain 2>/dev/null) ]]; then git_info=$(printf "\033[33m  %s\033[0m" "$branch"); else git_info=$(printf "\033[32m  %s\033[0m" "$branch"); fi; fi; context_info=""; pct=$(echo "$input" | jq -r '.context_window.used_percentage // empty'); if [ -n "$pct" ]; then pct_int=$(printf '%.0f' "$pct"); if [ "$pct_int" -lt 50 ]; then color="\033[32m"; elif [ "$pct_int" -lt 75 ]; then color="\033[33m"; else color="\033[31m"; fi; context_info=$(printf " \033[2m|\033[0m ${color}%d%%\033[0m ctx" "$pct_int"); fi; rate_info=""; five=$(echo "$input" | jq -r '.rate_limits.five_hour.used_percentage // empty'); week=$(echo "$input" | jq -r '.rate_limits.seven_day.used_percentage // empty'); if [ -n "$five" ] || [ -n "$week" ]; then rate_parts=""; [ -n "$five" ] && rate_parts=$(printf "5h:%d%%" "$(printf '%.0f' "$five")"); [ -n "$week" ] && rate_parts="$rate_parts${rate_parts:+ }$(printf '7d:%d%%' "$(printf '%.0f' "$week")")" ; rate_info=$(printf " \033[2m|\033[0m \033[33m%s\033[0m" "$rate_parts"); fi; hostname=$(hostname -s); style_info=""; if [ "$output_style" != "default" ]; then style_info=$(printf " \033[2m|\033[0m \033[36m%s\033[0m" "$output_style"); fi; printf "\033[32m%s\033[0m@\033[34m%s\033[0m in \033[36m%s\033[0m%s \033[2m|\033[0m \033[35m%s\033[0m%s%s%s" "$USER" "$hostname" "$current_dir" "${git_info:+ $git_info}" "$model" "$style_info" "$context_info" "$rate_info"
